#include <list>
#include <algorithm>

void remove_even(std::list<int>& l) {
    // CORRECT: Uses optimized member function (O(N))
    l.remove_if([](int x) { return x % 2 == 0; });
}

void remove_val(std::list<int>& l) {
    // CORRECT: Removes all instances of 5
    l.remove(5);
}

// Note: Using std::remove on list requires a non-standard approach 
// or is extremely inefficient, highlighting why the member function exists.
